const $=id=>document.getElementById(id);
let key='',filter='',offset=0,current=null,selection=0,role='',polling=false,session=0;
const names={queued:'已排队',approval_queued:'审批已入队',retrying:'等待自动重试',auto_rejected:'自动拒绝退款',auto_approved:'自动批准',running:'调查中',awaiting_approval:'等待审批',escalated:'转人工核查',answered:'已答复',refunded:'已模拟退款',already_refunded:'已拦截重复退款',rejected:'已拒绝',closed:'人工已关闭',failed:'调查失败'};
const message=text=>$('message').textContent=text;
async function api(path,body){let r;try{r=await fetch('/api'+path,{method:body?'POST':'GET',headers:{'X-API-Key':key,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});}catch{throw Error('无法连接服务，请检查 start-local.ps1 是否仍在运行');}const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));return data;}
function add(parent,tag,text,cls){const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;parent.append(e);return e;}
async function refresh(){const rows=await api(`/runs?limit=20&offset=${offset}&status=${encodeURIComponent(filter)}`.replace('&status=','&status='));$('rows').replaceChildren();if(!rows.length)add($('rows'),'tr','暂无工单');for(const r of rows){const tr=add($('rows'),'tr','');const td=add(tr,'td',r.ticket);add(td,'div',r.id.slice(0,8));add(tr,'td',r.order_id);add(add(tr,'td',''),'span',names[r.status]||r.status,'badge');add(tr,'td',new Date(r.created_at).toLocaleString());const b=add(add(tr,'td',''),'button','查看','secondary');b.onclick=()=>show(r.id).catch(e=>message(e.message));}$('page').textContent=`第 ${offset/20+1} 页`;$('prev').disabled=offset===0;$('next').disabled=rows.length<20;}
function render(r,preserveInputs=false){current=r;$('detail').hidden=false;$('detailstatus').textContent=names[r.status]||r.status;$('description').textContent=r.ticket;const s=r.state||{};$('checks').replaceChildren();for(const check of s.result?.checks||[])add($('checks'),'p',`${check.passed?'满足':'不满足'}：${check.name}`);if(s.result?.decision_source)add($('checks'),'p',`决策方式：${{automatic:'自动处理',human:'人工审批',manual_required:'等待人工审批',system:'系统分流'}[s.result.decision_source]||s.result.decision_source} · ${s.result.policy_version||'旧版规则'}`);$('facts').textContent=s.order?`${s.order.id||'未知订单'} · ¥${((s.order.amount||0)/100).toFixed(2)} · 签收 ${s.order.days??'未知'} 天 · ${s.order.used?'已使用':'未使用'}`:'调查尚无订单结果';$('proposal').textContent=s.result?.reason||s.proposal?.reason||r.error||'尚无处理建议';$('conflicts').hidden=!s.conflicts?.length;$('conflicts').textContent=(s.conflicts||[]).join('；');$('evidence').replaceChildren();for(const e of s.evidence||[]){const box=add($('evidence'),'div','','evidence-chunk');add(box,'strong',e.title||e.id);add(box,'div',`${e.source||e.id}${e.line_start?' · 第 '+e.line_start+'–'+e.line_end+' 行':''} · 版本 ${e.version||e.id}`);add(box,'p',e.text);if(e.chunk_id)add(box,'small',`片段 ${e.chunk_id}`)};$('trace').replaceChildren();if(s.skill)add($('trace'),'p',`已加载技能：${s.skill.name} · ${s.skill.sha256.slice(0,12)}`);for(const t of s.trace||[])add($('trace'),'p',[t.node,t.transport,t.tool,(t.tools||[]).join(' / '),names[t.status]||t.status].filter(Boolean).join(' · '));$('approval').hidden=r.status!=='awaiting_approval'||!['reviewer','admin'].includes(role);$('review').hidden=r.status!=='escalated'||!['reviewer','admin'].includes(role);$('audit').textContent=r.approval?`审批记录：${r.approval.approved?'同意':'拒绝'} · ${r.approval.reason}`:r.review?`人工处理：${r.review.resolution}`:'';if(!preserveInputs){$('reason').value='';$('resolution').value='';}$('jobinfo').textContent=r.job?`任务类型：${r.job.kind==='approval'?'审批执行':'调查'} · 已完成尝试 ${r.job.attempts} 次${r.job.last_error?' · '+r.job.last_error:''}`:'';$('retry').hidden=role!=='admin'||r.status!=='failed';}
async function show(id){const token=++selection;const r=await api('/runs/'+id);if(token===selection)render(r);}
$('authform').onsubmit=async e=>{e.preventDefault();key=$('key').value;try{const c=await api('/config');role=c.role;session++;$('logout').hidden=false;$('createpanel').hidden=role==='reviewer';$('monitor').hidden=role!=='admin';$('mode').textContent=`${c.mode==='live'?'真实模型':'规则演示'} · ${c.model} · ${c.database} · ${{operator:'运营',reviewer:'审批',admin:'管理员'}[role]}`;const orders=await api('/orders');$('order').replaceChildren();for(const o of orders){const op=add($('order'),'option',`${o.id} · ¥${o.amount/100} · ${o.used?'已使用':'未使用'} / ${o.days} 天`);op.value=o.id;}$('login').hidden=true;$('workspace').hidden=false;$('key').value='';await refresh();await monitor();message('已连接，任务在后台持续处理');}catch(err){key='';message(err.message);}};
$('createform').onsubmit=async e=>{e.preventDefault();$('submit').disabled=true;message('正在提交工单…');try{const r=await api('/runs',{ticket:$('ticket').value,order_id:$('order').value});selection++;render(r);await refresh();message('已加入后台队列，页面会自动更新结果');}catch(err){message(err.message);await refresh().catch(()=>{});}finally{$('submit').disabled=false;}};
async function decide(approved){if(!current)return;const reason=$('reason').value.trim();if(reason.length<2)return message('请填写至少两个字的审批理由');const id=current.id;$('accept').disabled=$('reject').disabled=true;try{const r=await api(`/runs/${id}/approval`,{approved,reason});if(current.id===id)render(r);await refresh();message('审批已记录，后台正在执行');}catch(e){message(e.message);}finally{$('accept').disabled=$('reject').disabled=false;}}
$('accept').onclick=()=>decide(true);$('reject').onclick=()=>decide(false);
$('closecase').onclick=async()=>{const resolution=$('resolution').value.trim();if(resolution.length<2)return message('请填写核查结论');$('closecase').disabled=true;try{render(await api(`/runs/${current.id}/review`,{resolution}));await refresh();message('人工处理已记录');}catch(e){message(e.message);}finally{$('closecase').disabled=false;}};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;offset=0;$('listtitle').textContent=b.textContent;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));if(key)refresh().catch(e=>message(e.message));});
$('refresh').onclick=()=>refresh().catch(e=>message(e.message));$('prev').onclick=()=>{offset=Math.max(0,offset-20);refresh().catch(e=>message(e.message));};$('next').onclick=()=>{offset+=20;refresh().catch(e=>message(e.message));};
// Optional browser WebMCP navigation; financial actions remain explicit UI/API operations.
if(document.modelContext?.registerTool){const lifetime=new AbortController();window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});Promise.resolve(document.modelContext.registerTool({name:'resolveflow_open_ticket',description:'打开已存在的工单并展示详情。需要先在页面授权。不会审批或退款。',inputSchema:{type:'object',properties:{run_id:{type:'string'}},required:['run_id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async input=>{if(!key)throw Error('请先在页面授权');if(!input||typeof input.run_id!=='string'||!/^[0-9a-f-]{36}$/i.test(input.run_id))throw Error('无效工单编号');await show(input.run_id);return{id:current.id,status:current.status};}},{signal:lifetime.signal})).catch(()=>{});}

async function monitor(){if(role!=='admin')return;const m=await api('/metrics');$('metrics').textContent=`在线 Worker：${m.workers_online} · 执行尝试：${m.attempts.total} · 失败尝试：${m.attempts.failed} · 平均 ${m.attempts.avg_ms||0} ms · P95 ${Math.round(m.attempts.p95_ms||0)} ms · 当前失败工单：${m.runs.failed||0}`;}
$('logout').onclick=()=>{key='';role='';session++;selection++;current=null;$('knowledgeresults').replaceChildren();$('workspace').hidden=true;$('detail').hidden=true;$('login').hidden=false;$('logout').hidden=true;$('mode').textContent='等待连接';message('已退出当前角色');};
$('retry').onclick=async()=>{if(!current)return;$('retry').disabled=true;try{render(await api(`/runs/${current.id}/retry`,{}));await refresh();message('已重新入队，将从检查点恢复');}catch(e){message(e.message);}finally{$('retry').disabled=false;}};
setInterval(async()=>{if(!key||polling||document.hidden)return;polling=true;const ownSession=session;try{await refresh();if(current){const id=current.id;const r=await api('/runs/'+id);if(session===ownSession&&current?.id===id)render(r,true);}if(session===ownSession)await monitor();}catch(e){if(session===ownSession)message(e.message);}finally{polling=false;}},4000);

$('knowledgeform').onsubmit=async event=>{
  event.preventDefault();const ownSession=session;const query=$('knowledgequery').value.trim();
  $('knowledgesubmit').disabled=true;
  try{const result=await api('/knowledge?query='+encodeURIComponent(query));
    if(session!==ownSession)return;
    $('knowledgeresults').replaceChildren();
    if(!result.results.length)add($('knowledgeresults'),'p','没有检索到相关政策，请转人工核查。');
    for(const hit of result.results){const box=add($('knowledgeresults'),'article','','evidence-chunk');
      add(box,'h3',hit.title);add(box,'small',`${hit.source} · 版本 ${hit.version} · 第 ${hit.line_start}–${hit.line_end} 行`);
      add(box,'p',hit.text);}
  }catch(error){if(session===ownSession)message(error.message);}
  finally{$('knowledgesubmit').disabled=false;}
};
